INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('f1-2020-deluxe-schumacher-edition', 135961, '2020-07-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2t8y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10fm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 2020: Deluxe Schumacher Edition', 'The entire F1 2020 game and the “Deluxe Schumacher Edition” DLC Content plus the “Seventy Edition” DLC Content and 3 days early access. Celebrate the record-breaking F1 career of the legendary Michael Schumacher. Take to the circuit in four of his most iconic cars and receive exclusive content including Michael Schumacher-themed multiplayer car liveries, helmets, race suits, and a podium celebration emote. You can also embark on your career using a Michael Schumacher driver model. Iconic Michael Schumacher cars: 1991 Jordan 191, 1994 Benetton B194, 1995 Benetton B195, 2000 Ferrari F1-2000. Exclusive Michael Schumacher in-game model, race suits, helmet designs and podium celebration emote and unique Schumacher-inspired multiplayer car liveries.' FROM games WHERE igdb_id = 135961 ON CONFLICT (game_id, language_code) DO NOTHING;
