INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '封神策', '《封神策》是一款可以自创修炼仙法的封神修仙题材动作游戏。你将扮演个性的仙门奇人，进入到殷商封神时期，帮助哪吒辅佐周文王周武王讨伐商纣，与妖邪斗智斗勇。在这里你可以自由修炼千百种仙法、道法、心法，组合仙法技能从而自创出一套属于你自己的特殊技能连招，华丽撼动天地的特效满屏释放！挑战神魔，收集神器都是小意思，你还能创立自己的仙门成为开山鼻祖，亦或是打遍全服玩家，成就神界霸主！' FROM games WHERE igdb_id = 128325 ON CONFLICT (game_id, language_code) DO NOTHING;
