INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Book of Distance', 'The Book of Distance blends techniques from mechanical sculpture, film, and stage to redefine personal storytelling in virtual reality. Family archives add a haunting layer of realism. 2D and 3D hand-crafted sets reminiscent of Japanese woodblock prints, evocative character design, and seamless choreography combine with surprising moments of interaction to gently whisk us across the ocean and through the years.' FROM games WHERE igdb_id = 161568 ON CONFLICT (game_id, language_code) DO NOTHING;
