INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Clans', 'A true, FIRST VR Street Fight! You’re just a regular guy, doing your best to get by, but you made your choices and now you’re in debt to the mafia. The only way you are going to save yourself is to fight. Prepare to engage in combat with no limits, no rules. You fight to win, you win to survive.' FROM games WHERE igdb_id = 130224 ON CONFLICT (game_id, language_code) DO NOTHING;
