INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Way of Boy: Another Way', 'Way of Boy: Another Way is a 2D action-adventure game in the series “Way of Boy”. You will plunge again into the so-called "Alternative Russia" in the shoes of the new protagonist, which is the exact opposite of the former. This will be reflected not only in the plot, but also in the gameplay, as you run in an opposite direction, an atypical direction for most platformers.' FROM games WHERE igdb_id = 132672 ON CONFLICT (game_id, language_code) DO NOTHING;
