INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.W.''s Nightmare', 'D.W. ''s Nightmare is a short horror game in which you are playing as D.W. Read. Your doll has been cursed. It''s up to you to survive 3 minutes by constantly finding where the doll spawns. Don''t get too comfortable. If you take too long, the doll will kill you. Will you step up to the challenge or be the doll''s first victim?' FROM games WHERE igdb_id = 248212 ON CONFLICT (game_id, language_code) DO NOTHING;
