INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brightstone Mysteries: Paranormal Hotel', 'Meet the ancient Egyptian cult in a search of almighty artifact, Marcus Antonius, King Arthur and many others who tried to kept this omni-powerful object hidden away from those who wanted to use its terrible powers for conquering the world and stop the evil from raising from its grave! - Lead a young detective and confront the ancient Egyptian cult - Meet King Arthur, Cleopatra, Marcus Antonius and other historical characters - Explore the mystical old castle and over 50 other locations - Search the "underworld" and discover the supernatural - Help save the world from the ultimate evil' FROM games WHERE igdb_id = 87596 ON CONFLICT (game_id, language_code) DO NOTHING;
