INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-glitch-dash', 146221, '2020-07-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yhr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arada.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Glitch Dash', 'Crack your knuckles and take a deep breath because the ultimate twitch runner has arrived. It’s called Super Glitch Dash for a reason, people: because it’s really, really super. Immerse yourself in jaw-dropping next-generation visuals that pulsate to the beat of the rhythm-driven gameplay. Feel the rush of your reflexes as you swipe your way past axes, hammers, lasers, meat grinders and spikes while trying to navigate the insane obstacle courses that comprise each stage. Grind rails, flip upside down, and scream into all-new indoor environments as the rollercoaster-like worlds unfold before your very eyes. We promise: surviving has never been so much fun. So if you’re looking for a really challenging impossible runner, then Super Glitch Dash is the game for you! Features • Simple controls, swipe to move • Spectacular twitch gameplay with unpredictable courses that zoom past you in the first-person • Incredible cutting-edge graphics take full advantage of powerful devices • Epic beat driven gameplay thumps to a grooving soundtrack • Make a Perfect Run and grab every collectible for the ultimate bragging rights Play today and test your skills!' FROM games WHERE igdb_id = 146221 ON CONFLICT (game_id, language_code) DO NOTHING;
