INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stoes: Sorrow Song of Bounty Hunter', 'At first glance, Steos looks like a side-scrolling shooting game, but you are piloting a walking artillery unit, and everybody thinks you are expendable! It’s time to make everyone stop underestimating you and fight back! Yes, each stage is just one screen, and it’s totally nightmare difficulty.' FROM games WHERE igdb_id = 147843 ON CONFLICT (game_id, language_code) DO NOTHING;
