INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel''s Spider-Man: Miles Morales - Launch Edition', 'In the latest adventure in Marvel''s Spider-Man universe, teenager Miles Morales is adjusting to his new home while following in the footsteps of his mentor, Peter Parker, as a new Spider-Man. But when a fierce power struggle threatens to destroy his new home, the aspiring hero realizes that with great power, there must also come great responsibility. To save all of Marvel''s New York, Miles must take up the mantle of Spider-Man and own it.
