INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts: Melody of Memory', 'Kingdom Hearts: Melody of Memory is a rhythm action game developed and published by Square Enix for the PlayStation 4, Xbox One, and Nintendo Switch. It is the fourteenth installment in the Kingdom Hearts series. The game features over 140 songs from the series and the ability to play as over 20 characters. Additionally, Kairi''s story is continued from the end of the Kingdom Hearts III Re Mind downloadable content.
