INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic World Evolution: Complete Edition', 'Build your own Jurassic World for the first time or relive the adventure on the go with Jurassic World Evolution: Complete Edition! Packed with every piece of downloadable content available, Jurassic World Evolution: Complete Edition for Nintendo Switch includes all three major narrative expansions – Jurassic World Evolution: Return to Jurassic Park, Jurassic World Evolution: Claire’s Sanctuary, and Jurassic World Evolution: Secrets of Dr. Wu- as well as four Dinosaur Packs and the Raptor Squad Skin Collection.' FROM games WHERE igdb_id = 138196 ON CONFLICT (game_id, language_code) DO NOTHING;
