INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zug in Sicht', 'Buying a ticket, finding the way to the right track, catching the train on time - all this is no problem for you? But what does it look like if you have an impaired vision? Find out if you can make the parkour through the train station in the learning game Zug in Sicht. The game was developed by Gentle Troll on behalf of the initiative "Woche des Sehens".' FROM games WHERE igdb_id = 383972 ON CONFLICT (game_id, language_code) DO NOTHING;
