INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Name is Mayo 2', 'This is a clicker game about a mayonnaise jar. It’s also creamy, dreamy and properly sequel-y! Right in the middle of the Next-Gen hardware hurricane, comes the true next-gen game everyone’s been waiting for! ...Not this one; but it’s close! This... is the touching story about a disorganized Mayo jar, who just can’t get its sheets together.' FROM games WHERE igdb_id = 141693 ON CONFLICT (game_id, language_code) DO NOTHING;
