INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Water Park: Fun Water Slides', 'Do you like active rest and adrenalin? Do you like roller-coasters and other extreme races? Then let''s go to the water park together with Hippo! Funny kids games, waterslides, jumps into water and other unbelievable attractions are waiting for us! It is time to jump into swimming pool, swim and have fun! Call friends to try new crazy races on water slides. Water park simulator is created for all the family, these are the best kids games!' FROM games WHERE igdb_id = 96974 ON CONFLICT (game_id, language_code) DO NOTHING;
