INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Never Date Werewolves', 'Dating a werewolf means you’re left with a litter of kids who turn into cubs when they get upset. You’ve got the silver out of the house, meat in the fridge – but contrary to your ex, you can’t turn into a wolf when the cubs decide to do a runner!' FROM games WHERE igdb_id = 130137 ON CONFLICT (game_id, language_code) DO NOTHING;
