INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Battle of Angels', 'The game where you play as an Angel. After watching an event taking place. The Angel will then announce his idea for that event''s ending. The demon angel, in contrast, will answer his idea for that same events ending. The winner of the boxing fight will determine the actual ending. Save your people!' FROM games WHERE igdb_id = 156603 ON CONFLICT (game_id, language_code) DO NOTHING;
