INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Letter Wizard', 'Remember Bookworm? This game is as close as you''ll get. A wonderful and relaxing word game. Connect neighboring letters to make words. Use bonus tiles to increase the word score. When red tiles reach the bottom the game is over. Score big when you find words within categories like food and science. Find the bonus word for double points. Word dictionary with over 400,000 words! Stats for current rank, current game and all-time. Game Center leaderboards.' FROM games WHERE igdb_id = 175856 ON CONFLICT (game_id, language_code) DO NOTHING;
