INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '墨心：波云诡船', '《墨心》是一款将古代中国幻想元素和悬疑科幻相融合的国产视觉小说。男主（你）从昏迷中醒来丧失了记忆，发现自己和另外两女一男困于巨轮密室中。面对匪夷所思的船体变异，恐怖致命的巨型怪物，你们能否成功逃脱？而这超自然的现象，似乎跟一件千年前的战国墨家宝物有关......' FROM games WHERE igdb_id = 156922 ON CONFLICT (game_id, language_code) DO NOTHING;
