INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-train-express-plus', 136644, '2020-10-07', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar33zu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-Train Express+', 'The player is the president of a railway company who lays track, runs trains, and takes people from station to station. This creation of flows of people brings about gradual changes in the areas around stations, and before long, a city centered around these stations forms and grows. Skyscrapers and department stores are built in front of stations, and the city grows larger; if the number of station users increases, the number of railway users also increases. With the acquired revenue, the player can maintain a railway network and set up subsidiary companies to build residential areas and entertainment facilities along the railroad, and by breaking into the operation of other types of transportation such as buses and trucks, can grow the overall map into one of a large city.' FROM games WHERE igdb_id = 136644 ON CONFLICT (game_id, language_code) DO NOTHING;
