INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inside Her Bedroom', 'Inside Her (bedroom) is a 2D action puzzle game about monster girls'' bedrooms. Move two mirrored characters to get items scattered around their rooms. Use their special skills to complete the puzzles and uncover their secrets. Every monster girl has a unique skill like moving through walls, pushing items, etc. Solve the puzzles to increase their desire.' FROM games WHERE igdb_id = 391827 ON CONFLICT (game_id, language_code) DO NOTHING;
