INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Swipe Right', 'Heroes Swipe Right is a challenging dungeon crawler where you form your party of adventurers using a dating app, swiping left to pass on the losers and right to pair with capable allies. Every potential match comes with their strengths and quirks, many of which drastically alter the nature of the game.' FROM games WHERE igdb_id = 121798 ON CONFLICT (game_id, language_code) DO NOTHING;
