INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('b-dot-o-o-dot-l-master-labyrinth-puzzles', 147565, '2020-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5avy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1e3o.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'B.O.O.L: Master labyrinth puzzles', 'B.O.O.L: Master labyrinth puzzles is a fun and challenging puzzle game for everyone. B.O.O.L. stands for ''Box Out Of Labyrinth'' and means to get the box out of the labyrinth and describes the aim of the game. Your task is to get the box out of the labyrinth to the target. This sounds like a simple task? You did the calculation without the puzzle masters. The game box cannot be moved freely, but only up, down, left and right and only up to the next obstacle without stopping in between. But that''s not all, you only have a certain number of moves at your disposal. Get ready and face the challenge of more than 120 labyrinth puzzles. - Puzzles in three difficulty levels. - Puzzles contain doors, switches and the four elements earth, fire, water and air. - Give your creativity free rein and create your own labyrinth puzzles with the editor on 100 free memory slots.' FROM games WHERE igdb_id = 147565 ON CONFLICT (game_id, language_code) DO NOTHING;
