INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NuclearRifle', '《NuclearRifle》 is an FPS shooting game. The protagonist wakes up from a small town house, only to find that the doors are locked. From time to time, strange sounds of biting came from nearby houses, and the exit of the town were sealed. What happened to the town? Can the protagonist escape?' FROM games WHERE igdb_id = 384527 ON CONFLICT (game_id, language_code) DO NOTHING;
