INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sniper-ghost-warrior-contracts-complete-edition', 141649, '2020-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaked.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sniper Ghost Warrior Contracts: Complete Edition', 'Become the ultimate in in the most realistic modern Warfare sniping game available. Engage in an immersive single-player campaign across large, open-ended maps. Tactical thinking, stealth approach and precision in execution of long shots required. Fulfil contracts that offer clear objectives with a fixed monetary reward and options to complete bonus challenges for payouts. With hundreds of ways to take down a wide range of targets, contracts offers precise, strategic sniping gameplay at its absolute best. Play as a paid in; a hit man for hire, and beware of rival snipers who won''t hesitate to disrupt your best-laid plans.' FROM games WHERE igdb_id = 141649 ON CONFLICT (game_id, language_code) DO NOTHING;
