INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Pathless', 'The Pathless is a mythic adventure where you play as the Hunter, a skilled archer who explores a mysterious cursed island with an eagle companion. Your goal is to lift an unnatural shroud of darkness that plagues the world. As you bound acrobatically through dense forests, you will hunt prey, discover ancient ruins, and form a deep bond with your eagle. But beware: dangerous spirits also lurk in the woods. If you aren''t careful, you may become the hunted yourself.' FROM games WHERE igdb_id = 113118 ON CONFLICT (game_id, language_code) DO NOTHING;
