INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chip’s Tips', 'Skip and his dog Chip are the stars of everyone''s favorite kids’ TV show, Chip’s Tips! As Chip is a dog and therefore incapable of most tasks, Skip has to work alone to has to get everything ready for tonight''s Halloween party. Can you help him find everything he needs for the perfect spooky celebration? What could possibly go wrong!? A classic FMV adventure game in the style of Harvester.' FROM games WHERE igdb_id = 391988 ON CONFLICT (game_id, language_code) DO NOTHING;
