INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goosebumps: Dead of Night', 'Slappy the Dummy has unleashed a nightmare of Goosebumps monsters, and they’re all out to get you! Escape from frightening creatures like the Graveyard Ghoul, Lawn Gnomes, Annihilator 3000, Murder the Clown, and the Werewolf of Fever Swamp as you collect the scattered pages of Slappy''s book to seal him away. You’ll explore infamous Goosebumps locales for clues, hide from monsters, and solve Slappy’s devious puzzles.' FROM games WHERE igdb_id = 134371 ON CONFLICT (game_id, language_code) DO NOTHING;
