INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('interactive-portraits-trans-people-in-japan', 134988, '2020-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tct.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interactive Portraits: Trans People in Japan', 'This is a series of works that came out of a residency carried out in early 2018 in Tokyo, with the Creator Ikusei project, which is supported by the Japanese Agency for Cultural Affairs. I adopted research techniques from ethnography and history, such as open-ended interviews and participant observation, and developed a method of representing the results of this research in a playful and interactive form that draws heavily from familiar interaction design patterns such as the tamagotchi-style virtual pet and role-playing game multiple-choice dialogue systems.' FROM games WHERE igdb_id = 134988 ON CONFLICT (game_id, language_code) DO NOTHING;
