INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War-Torn Dreams', 'War-Torn Dreams is a 2D, story-rich, side scrolling action game, set in the wasteland of the USA, plagued with constant war. Following the collapse of the economy, government, and society, you must brave heavily armed militia, lawless gangs, dangerous streets, desolate buildings and underground bunkers on your quest to escape this post-apocalyptic wasteland alive. The road to a new life is paved with danger, hope and constant reminders of everything that''s been lost.' FROM games WHERE igdb_id = 132983 ON CONFLICT (game_id, language_code) DO NOTHING;
