INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Unlimited', 'Buckle up! Get ready to race around Hot Wheels Islands! We’re all about awesome cars, monster trucks, fun racing games, crazy challenges, and building the coolest race tracks around. Head on over to Hot Wheels City to test your skills with fun puzzle or car racing challenges. Race solo or compete against friends! Start your engines, this is going to be an awesome ride!' FROM games WHERE igdb_id = 335815 ON CONFLICT (game_id, language_code) DO NOTHING;
