INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander Keen in Keen Dreams: Definitive Edition', 'Commander Keen is back. In the modernised Definitive Edition of the lost episode "Keen Dream", Keen has to fend off a nasty nightmare about evil vegetables. The Definitive Edition features full widescreen support, twelve all-new levels - doubling the length over the 1990 original - and a full music score. The game structure has been reworked to make the game a more modern experience without sacrificing any of the original charm!' FROM games WHERE igdb_id = 146755 ON CONFLICT (game_id, language_code) DO NOTHING;
