INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stream Draws', 'Stream Draws With Twitch is a game that lets the stream chat draw amazing (pixel) art during a live stream. Highly customizable options, 26000 known color names or HTML-Color codes. Draw pixel by pixel or with lines. It has an integrated replay function and saves the final image as screenshot and pixel art.' FROM games WHERE igdb_id = 139448 ON CONFLICT (game_id, language_code) DO NOTHING;
