INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farmer Sim 2020', 'Farmer Sim 2020 will let you become a real farmer! Take yourself in an awesome open world and start enjoying this great farming simulator. Harvest different types of crops, manage your livestock - cows, sheeps, turkeys, pigs. Experience the farming life, transport woods, hays, etc... This Farmer Simulator will allow you to play with many machines, tractors, combines, trucks, trailers, plows, seeders, etc... The next-gen graphics will completely immerse you in the real farming world.' FROM games WHERE igdb_id = 147694 ON CONFLICT (game_id, language_code) DO NOTHING;
