INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Ennea', 'Planet Ennea is a short game made for the fourth Dream Diary Jam using the RPG Maker VX Ace engine. It focuses around a newly built robot and their desire to understand the lives and emotions of those around them. It features way more text than your standard Yume Nikki fangame, but that''s fine, isn''t it? You won''t talk much, but you''ll have the chance to listen.' FROM games WHERE igdb_id = 229653 ON CONFLICT (game_id, language_code) DO NOTHING;
