INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Best Friend Forever', 'Best Friend Forever is the world’s first simulation game to combine pet care and dating (just not necessarily at the same time). Train, pat and play with your very own dog to form a bond that will last the ages. With your four-legged companion by your side, meet, woo and cherish the many cuties of Rainbow Bay’s thriving singles scene. Pet the dogs - then the owners.' FROM games WHERE igdb_id = 121749 ON CONFLICT (game_id, language_code) DO NOTHING;
