INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Tyria', 'In this loveletter to classics like The Legend of Zelda or Neutopia, you take the role of the chosen hero of light to awaken the Goddess Tyria from her nightmare! Can you master all challenges on your journey to find the seven Light Crysts? Use your sword, shield and powerful magical tools to achieve your goal and save the world!' FROM games WHERE igdb_id = 135808 ON CONFLICT (game_id, language_code) DO NOTHING;
