INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dotori', 'Rico the Squirrel was living a peaceful life collecting acorns. It was another peaceful day doing his work with his sister Lottie ...until an owl came out of nowhere and kidnapped his sister! Now Rico must embark on a dangerous journey to save Lottie…. • Explore places full of mysteries with Rico the Squirrel! • Run, jump, and throw! Perform colorful actions with simple controls! • Discover and collect acorns hidden in the stage! • Fight bosses and survive their fierce attacks! • ...and unlock bonus stages testing your control! Can Rico rescue his sister Lottie? "Wait, Lottie…. I''m coming to save you!"' FROM games WHERE igdb_id = 143600 ON CONFLICT (game_id, language_code) DO NOTHING;
