INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword Art Online: Alicization Lycoris', 'Following the events of the SWORD ART ONLINE Alicization anime series, SWORD ART ONLINE Alicization Lycoris finds Kirito in a mysterious but familiar virtual world, “Underworld,” where A.I.s behave like humans. As players take control of Kirito, they will relive heart-pounding scenes from the series through intense combat. Players will also encounter fan favorite characters including Eugeo, Alice, Administrator, and many more. A wide world awaits Kirito and his friends in this exciting adaptation to the SWORD ART ONLINE Alicization series.' FROM games WHERE igdb_id = 116805 ON CONFLICT (game_id, language_code) DO NOTHING;
