INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Catcher', 'A Low res horror game 14 years in the making, Soul Catcher has the player take the role of one of six characters who find themselves in a nightmarish remote mountainside trying to save a loved one from a demon worshiping cult. Navigate the mansion, solve the puzzles and evade the horrors that lurk.' FROM games WHERE igdb_id = 169721 ON CONFLICT (game_id, language_code) DO NOTHING;
