INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sakuna-of-rice-and-ruin', 36595, '2020-11-10', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob1u5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4mf4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakuna: Of Rice and Ruin', 'In Sakuna: Of Rice and Ruin, players take on the role of Sakuna, a proud yet lonely harvest goddess who is banished to a dangerous island with a group of outcast humans. Sakuna tames the island by defeating demons using farm tools as weapons while also making ample use of her “celestial scarf,” a magical item that allows her to grapple distant enemies and platforms. Along the way, she establishes a home in a mountain village, which serves as a base of operations for crafting weapons and cooking food. Additionally, as a harvest goddess, she grows rice by following a detailed process that encompasses everything from planting to harvesting. Through this process, across each of the four seasons, she’s able to improve the harvest and hone her battle skills alike.' FROM games WHERE igdb_id = 36595 ON CONFLICT (game_id, language_code) DO NOTHING;
