INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoops Madness', 'The intense physical basketball play, fast-paced action, and many thrilling and fun arcade game modes will leave you breathless as you take over the court in a larger than life arena surrounded by exhilarating sights and sounds that only the pros get to experience. With all sorts of thrilling and fun arcade game modes that you can’t do anywhere else but in Hoops Madness⏤you’ll never want to play in reality again!' FROM games WHERE igdb_id = 140354 ON CONFLICT (game_id, language_code) DO NOTHING;
