INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('black-datura-and-red-goat', 157828, '2020-08-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45w5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar20rh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Datura & Red Goat', '苏醒之时，他正处于昏暗的木屋之中。自己的身份、过去的经历，全都无法想起。很快，他发觉自己正处于一个异常的空间，到处都是谜题和陷阱，还有一些古怪的居民。在前行的途中，也不断与同样被困在此处的人成为了同伴。道路的前方，是救赎，还是绝望？这是一个围绕着“诅咒”与“救赎”的故事。' FROM games WHERE igdb_id = 157828 ON CONFLICT (game_id, language_code) DO NOTHING;
