INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Day Without Me', 'A Day Without Me is an intriguing adventure game with a high emphasis on puzzles. It combines adventure, horror and drama elements. Main character wakes up as the only person left in the whole city. Now he has to find out what’s happened, where has everyone gone and how to overcome a series of strange events happening in front of his own eyes.
