INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athletics Mania', 'Join a competition in track and field events. Running, jumping, throwing, pentathlon, heptathlon or decathlon, you can play all of these in Athletics Mania. Train, improve your skills, show your talent and win a gold medal in the biggest stadiums around the world. Do you have what it takes to stay on top of leaderboards and rankings in this summer sports game?' FROM games WHERE igdb_id = 272442 ON CONFLICT (game_id, language_code) DO NOTHING;
