INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayon Shin Chan: The Storm Called! Flaming Kasukabe Runner!!', 'Jump-action Crayon Shinchan game that anyone can easily play! Collect various costumes and friends and run through the city of Kasukabe and the world of movies! Everyone''s favorite five-year-old, Shinnosuke, makes a Fierce Dash to collect sweets and Golden Balls. Get lots of different costumes using Golden Balls, obtained by proceeding from one stage to another and completing special missions! Enjoy Shinchan and his friends wearing a variety of cosplay clothes, well-known to people familiar with anime and movies!' FROM games WHERE igdb_id = 130760 ON CONFLICT (game_id, language_code) DO NOTHING;
