INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jollibees-phase-2', 185848, '2020-04-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4asb.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jollibee''s: Phase 2', 'The player plays/works as an employee of the shipping company, LBM Shipments, Inc. (LBM Shipments Inc Warehouse). Their job is to transport boxes each night shift. To do this, they must use the workstation panel on the left side of the office that controls the conveyor belts and security systems. On the first night, 50 boxes must be transported to their respective conveyer belts. The boxes and tracks are labelled by a letter (A, B, C, D, and E). To transport them, the player needs to click and drag the node to the other corresponding side. The number of boxes increases by 25 boxes each new night, reaching its maximum of 100 boxes on Night 3. It is recommended to keep track of the box/track labels, otherwise errors will be added to the counter on the bottom left corner of the area on the screen. Errors are counted when a box is ignored or misplaced. If the player gets 1 error, 50$ will be removed from the paycheck at the end of the night. The maximum amount of errors the player can get is 15. If any more are added, the result will be a GAME OVER screen.
