INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fishing: North Atlantic', 'Commercial fishing in the North Atlantic! Discover the majestic world of Canadian Nova Scotia while admiring the vast diversity of ocean life. Search for the ocean’s gold with upgradable fishing boats and various types of fishing gear as you progress in your career.' FROM games WHERE igdb_id = 139507 ON CONFLICT (game_id, language_code) DO NOTHING;
