INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CircuiTree', 'CircuiTree is a rhythm-based circuitry building game where your goal is to keep the mother tree alive by building and repairing circuits before they cause irreparable damage. CircuiTree was made by Cody Bock (Neonalig) in 48 hours between 2020/04/18 to 2020/04/20 as part of Ludum Dare 46 for the theme ''Keep it Alive''.' FROM games WHERE igdb_id = 244982 ON CONFLICT (game_id, language_code) DO NOTHING;
