INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totally Reliable Delivery Service', 'Delivery Attempted. That''s the Totally Reliable Delivery Service guarantee! T.R.D.S. is a ragdoll physics simulation about terrible package delivery couriers. Work together using odd machinery, useful gadgets, and the wonders of physics to reliably deliver packages to their destination.' FROM games WHERE igdb_id = 114058 ON CONFLICT (game_id, language_code) DO NOTHING;